// NÃO editar à mão — rode o script novamente.

export type GcpTier = 'ProjectOwner' | 'Admin' | 'Editor' | 'Operator' | 'Developer' | 'Viewer' | 'Specialized'

export type GcpCategory = 'IAM' | 'Compute' | 'Storage' | 'BigQuery' | 'Kubernetes' | 'Database' | 'Networking' | 'Security' | 'DevOps' | 'Serverless' | 'AI' | 'Analytics' | 'Observability' | 'Billing' | 'Management'

export interface GcpRole {
  slug: string
  name: string
  roleId: string
  /** Texto oficial do Google. */
  description: string
  /** Classificação editorial do IAM Scope — não vem do Google. */
  tier: GcpTier
  /** Classificação editorial do IAM Scope — não vem do Google. */
  category: GcpCategory
  /** Classificação editorial do IAM Scope — não vem do Google. */
  isPrivileged: boolean
  /** Derivado de lowestResources (dado oficial). */
  scope: 'project' | 'org' | 'folder' | 'resource'
  /**
   * As permissões em si NÃO ficam aqui: são ~130 mil strings e iriam para o
   * bundle do cliente. Vivem em public/gcp-perms/<slug>.json, buscadas sob
   * demanda — mesmo desenho de AzureRbacRole.
   */
  permissionCount: number
  /** "Lowest-level resources where you can grant this role" (oficial). */
  lowestResources?: string[]
  /** Launch stage oficial, quando não é GA (ex.: 'Beta'). */
  stage?: string
  /**
   * Detectado no texto da descrição oficial.
   * A doc do Google não publica flag de depreciação — o launch stage só assume
   * GA ou Beta —, então esta contagem é um piso. O campo `stage: DEPRECATED`
   * existe na IAM API, usada por scripts/fetch-gcp-roles.js.
   */
  deprecated?: boolean
  /**
   * Presente só nas basic roles. O Google reclassificou Owner/Editor/Viewer
   * como legacy; as basic atuais são Admin/Writer/Reader.
   */
  kind?: 'basic' | 'legacy-basic'
  /**
   * Por que permissionCount é 0 nas basic roles: o Google não publica a lista
   * delas na documentação.
   */
  permissionsNote?: string
}

export interface GcpTierMeta {
  label: string; color: string; bg: string; description: string
}

